shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae4d7;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283e54;
    --alert-red: #9e2a2b;
    --barricade-gold: #c99700;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.8;
    overflow-x: hidden;
  }

  /* Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.75rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: 'Playfair Display', serif;
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .edition-badge {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    border-left: 1px solid var(--line-strong);
    padding-left: 0.85rem;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    background: var(--paper-card);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.32rem 0.75rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero-header {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .kicker-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.78rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 700;
  }

  .kicker-dot {
    width: 7px;
    height: 7px;
    background-color: var(--accent);
    border-radius: 50%;
    display: inline-block;
  }

  .article-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-weight: 800;
    font-size: clamp(2.1rem, 4.4vw, 3.6rem);
    line-height: 1.18;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.35rem;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .article-title {
    line-height: 1.26;
    letter-spacing: 0;
  }

  .hero-standfirst {
    font-family: 'Lora', 'Noto Serif SC', serif;
    font-size: clamp(1.08rem, 1.6vw, 1.28rem);
    line-height: 1.68;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
  }

  .meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.1rem;
    border-top: 1px solid var(--line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-name {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.03em;
  }

  .dateline-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.76rem;
    color: var(--muted);
    background: var(--paper-card);
    padding: 0.25rem 0.65rem;
    border: 1px solid var(--line);
  }

  /* Key Telemetry Strip */
  .telemetry-strip {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .telemetry-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    padding: 1.2rem 1.25rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .telemetry-card.accent-top {
    border-top-color: var(--accent);
  }

  .telemetry-num {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 2.1rem;
    font-weight: 800;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }

  .telemetry-card.accent-top .telemetry-num {
    color: var(--accent);
  }

  .telemetry-label {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.3rem;
  }

  .telemetry-sub {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.74rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Main Container & Editorial Grids */
  .editorial-container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 1.5rem 4rem;
  }

  .chapter-section {
    padding: 3rem 0;
    border-bottom: 1px solid var(--line-strong);
  }

  .chapter-section:last-of-type {
    border-bottom: none;
  }

  .chapter-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 1.5rem;
    font-weight: 700;
  }

  .chapter-kicker::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--line);
  }

  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(280px, 1fr);
    gap: 3rem;
    align-items: start;
  }

  /* Prose Styling */
  .prose-col {
    display: flex;
    flex-direction: column;
    gap: 1.4rem;
  }

  .prose-p {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
  }

  :host([lang="zh-CN"]) .prose-p {
    line-height: 1.96;
    letter-spacing: 0.01em;
  }

  .lead-p {
    font-size: 1.24rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 600;
    border-left: 4px solid var(--ink);
    padding-left: 1.25rem;
    margin-bottom: 0.35rem;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 0.15em;
    font-weight: 600;
    border-bottom: 1.5px solid var(--accent);
  }

  /* Side Rails & Dossiers */
  .rail-col {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
  }

  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
    position: relative;
  }

  .dossier-header {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 700;
    padding-bottom: 0.65rem;
    margin-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .dossier-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.18rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.35;
  }

  .vs-panel {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .vs-card {
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.9rem 1rem;
    border-left: 3px solid var(--ink);
  }

  .vs-card.critics {
    border-left-color: var(--accent);
  }

  .vs-tag {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--muted);
    margin-bottom: 0.3rem;
  }

  .vs-card.critics .vs-tag {
    color: var(--accent);
  }

  .vs-desc {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
    line-height: 1.55;
    color: var(--body);
  }

  /* Bespoke SVG Graphic Container */
  .svg-showcase {
    margin: 2.25rem 0 0.5rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.75rem;
  }

  .svg-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--line);
  }

  .svg-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-weight: 700;
    font-size: 1.25rem;
    color: var(--ink);
  }

  .svg-subtitle {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    color: var(--muted);
  }

  .svg-caption {
    margin-top: 0.85rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Airport Quote Callout (Split from p7.s2) */
  .verdict-quote {
    margin: 0.5rem 0;
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.65rem 1.85rem;
    border-left: 5px solid var(--barricade-gold);
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.32rem;
    font-weight: 700;
    line-height: 1.5;
    position: relative;
  }

  /* Forensic Verification Ledger */
  .verification-ledger {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.5rem;
    border: 1px solid var(--navy-line);
  }

  .ledger-kicker {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--barricade-gold);
    margin-bottom: 0.85rem;
    display: block;
  }

  .ledger-row {
    padding: 0.85rem 0;
    border-top: 1px solid var(--navy-line);
  }

  .ledger-row:first-of-type {
    border-top: none;
    padding-top: 0.25rem;
  }

  .ledger-val {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 1.2rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 0.2rem;
  }

  .ledger-lbl {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    color: #cbd5e1;
    line-height: 1.45;
  }

  /* Human Feature Section (Ishrat Ansari) */
  .human-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.6rem;
  }

  .discrepancy-grid {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    gap: 0.75rem;
    align-items: center;
    margin: 1rem 0;
    background: var(--paper);
    padding: 1rem;
    border: 1px solid var(--line);
  }

  .id-box {
    text-align: center;
  }

  .id-year {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    color: var(--muted);
    margin-bottom: 0.25rem;
  }

  .id-name {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-weight: 700;
    font-size: 1rem;
    color: var(--ink);
  }

  .id-arrow {
    font-family: 'JetBrains Mono', monospace;
    color: var(--accent);
    font-weight: 700;
    font-size: 1.1rem;
  }

  .pull-quote {
    margin: 1rem 0 0;
    padding: 1.35rem 1.5rem;
    background: var(--paper);
    border-left: 4px solid var(--accent);
    border-top: 1px solid var(--line);
    border-right: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
  }

  .pull-quote .quote-text {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.15rem;
    font-style: italic;
    color: var(--ink);
    line-height: 1.55;
    margin-bottom: 0.65rem;
  }

  :host([lang="zh-CN"]) .pull-quote .quote-text {
    font-style: normal;
    font-weight: 700;
  }

  .pull-quote .quote-attrib {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
  }

  .closing-question-box {
    margin: 0.5rem 0;
    padding: 1.5rem 1.75rem;
    background: var(--paper-card);
    border-left: 4px solid var(--accent);
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.38rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.48;
  }

  /* Footer */
  .editorial-footer {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Responsive Reflow */
  @media (max-width: 900px) {
    .telemetry-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .asymmetric-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
  }

  @media (max-width: 560px) {
    .masthead-inner {
      padding: 0.65rem 1rem;
    }
    .hero-header {
      padding: 2.25rem 1rem 1.75rem;
    }
    .telemetry-strip {
      grid-template-columns: 1fr;
      padding: 1.5rem 1rem;
    }
    .editorial-container {
      padding: 0 1rem 3rem;
    }
    .svg-showcase {
      padding: 1.1rem;
    }
    .discrepancy-grid {
      grid-template-columns: 1fr;
      text-align: center;
    }
    .lead-p {
      font-size: 1.12rem;
    }
    .prose-p {
      font-size: 1.04rem;
    }
  }
